/*
`$J_G$` = `$Y_1$``$Z_1$`^T + `$Y_2$``$Z_2$`^T 

`$Y_1$` =  [`$U_s$`
             0]
`$Z_1$` =  [ 0
             M`$U_s$`] 
`$Y_2$` =  [0
            -`$U_s$``$U_s$`^TK`$U_s$`]
`$Z_2$` =  [ M`$U_s$`
             0] 

where 
`$U_s$` : ℝ^(n × s)
M : ℝ^(n × n) 
K : ℝ^(n × n)

*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    MatrixD J_G;
    MatrixD Y_1;
    MatrixD Z_1;
    MatrixD Y_2;
    MatrixD Z_2;

    heartlib(
        const Eigen::MatrixXd & U_s,
        const Eigen::MatrixXd & M,
        const Eigen::MatrixXd & K)
    {
        const long n = U_s.rows();
        const long s = U_s.cols();
        assert( U_s.rows() == n );
        assert( M.rows() == n );
        assert( M.cols() == n );
        assert( K.rows() == n );
        assert( K.cols() == n );
        // `$Y_1$` =  [`$U_s$`
        //              0]
        MatrixD Y_1_0(n + 1, s);
        Y_1_0 << U_s,
        MatrixD::Zero(1, s);
        Y_1 = Y_1_0;
        // `$Z_1$` =  [ 0
        //              M`$U_s$`]
        MatrixD Z_1_0(n + 1, s);
        Z_1_0 << MatrixD::Zero(1, s),
        M * U_s;
        Z_1 = Z_1_0;
        // `$Y_2$` =  [0
        //             -`$U_s$``$U_s$`^TK`$U_s$`]
        MatrixD Y_2_0(n + 1, s);
        Y_2_0 << MatrixD::Zero(1, s),
        -U_s * U_s.transpose() * K * U_s;
        Y_2 = Y_2_0;
        // `$Z_2$` =  [ M`$U_s$`
        //              0]
        MatrixD Z_2_0(n + 1, s);
        Z_2_0 << M * U_s,
        MatrixD::Zero(1, s);
        Z_2 = Z_2_0;
        // `$J_G$` = `$Y_1$``$Z_1$`^T + `$Y_2$``$Z_2$`^T
        J_G = Y_1 * Z_1.transpose() + Y_2 * Z_2.transpose();
    }
};

